84	  print(
85	    varName: string,
86	    secretKeyOrValue: string | number | boolean,
87	    defaultValue?: string | undefined,
88	  ): string {
89	    varName = makePrivate(varName);
90	    if (isSecret(secretKeyOrValue)) {
91	      const withoutPrefix = unprefixSecret(secretKeyOrValue);
92	      const secretGetter = defaultValue
93	        ? `os.environ.get("${withoutPrefix}", "${defaultValue}")`
94	        : `os.environ.get("${withoutPrefix}")`;
95	      this.secrets[varName] = secretGetter;
96	      return varName;
97	    }
98	    if (defaultValue != null) {
99	      const secretGetter = `os.environ.get("${secretKeyOrValue}", "${defaultValue}")`;
100	      this.secrets[varName] = secretGetter;
101	      return varName;
102	    }
103	
104	    if (typeof secretKeyOrValue === "number") {
105	      return `${secretKeyOrValue}`;
106	    }
107	    // If its a number, return it as is
108	    if (typeof secretKeyOrValue === "number") {
109	      return `${secretKeyOrValue}`;
110	    }
111	    if (typeof secretKeyOrValue === "boolean") {
112	      return formatBoolean(secretKeyOrValue);
113	    }
114	    if (!secretKeyOrValue) {
115	      return "";
116	    }
117	
118	    return `"${secretKeyOrValue}"`;
119	  }
120	
121	  printInFString(
122	    varName: string,
123	    secretKeyOrValue: string | number | undefined | boolean,
124	    defaultValue?: string | undefined,
125	  ): string {
126	    if (secretKeyOrValue === undefined) {
127	      return "";
128	    }
129	    // If its a number, return it as is
130	    if (typeof secretKeyOrValue === "number") {
131	      return `${secretKeyOrValue}`;
132	    }
133	    if (typeof secretKeyOrValue === "boolean") {
134	      return formatBoolean(secretKeyOrValue);
135	    }
136	
137	    const value = this.print(varName, secretKeyOrValue, defaultValue);
138	    // If its a string, remove the quotes
139	    if (value.startsWith('"') && value.endsWith('"')) {
140	      return value.slice(1, -1);
141	    }
142	    // If its a variable, wrap it in curly braces
143	    return `{${value}}`;
144	  }
